-- ============================================================
-- Quiz coverage for cloud/aws-vpc, cloud/aws-s3, cloud/aws-rds
-- (Phase 3 batch 2 -- AWS Network & Data).
-- 60 questions total: 20 each, covering overview/fundamentals/
-- intermediate/advanced for all three technologies.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ====== AWS VPC ======

-- ---------- cloud/aws-vpc/overview ----------
('cloud', 'aws-vpc', 'overview', 'In an AWS VPC, what actually determines whether a subnet is "public" or "private"?', '["A checkbox you set when creating the subnet, which permanently fixes it as public or private", "Whether the subnet''s route table has a route sending 0.0.0.0/0 traffic to an Internet Gateway -- nothing else about the subnet''s configuration decides this", "Whether the subnet''s Security Groups allow inbound traffic from 0.0.0.0/0", "Whether the subnet is in the first Availability Zone of the region"]', 1, 'Public vs private is entirely a routing question, not a firewall question: a subnet with a 0.0.0.0/0 route to an Internet Gateway is public; one without it is private, regardless of how open or closed its Security Groups are.', 'beginner'),
('cloud', 'aws-vpc', 'overview', 'Why is a NAT Gateway placed inside a PUBLIC subnet, even though its whole purpose is to serve PRIVATE subnets?', '["It is a mistake commonly made in diagrams -- NAT Gateways actually belong in private subnets", "The NAT Gateway itself needs a route to the Internet Gateway to reach the internet on behalf of private-subnet resources -- only a public subnet has that route", "AWS requires all Gateway-type resources to be co-located in the same subnet type", "Placing it in a public subnet is only a cost-saving measure, not a functional requirement"]', 1, 'The NAT Gateway needs outbound internet access itself in order to forward traffic for private instances -- since only subnets with a route to the IGW have that, the NAT Gateway must live in a public subnet even though private-subnet resources are the ones using it.', 'beginner'),
('cloud', 'aws-vpc', 'overview', 'A Security Group allows inbound traffic on port 443. Do you also need to add an explicit outbound rule to allow the response traffic back out?', '["Yes, Security Groups require symmetric inbound and outbound rules for every connection", "No -- Security Groups are stateful, so return traffic for an already-allowed inbound connection is automatically permitted regardless of outbound rules", "Only if the Security Group has any inbound DENY rules configured", "Only for TCP traffic; UDP responses always need an explicit outbound rule"]', 1, 'Statefulness is the key distinguishing trait of Security Groups vs NACLs -- once inbound traffic is allowed in, the connection is tracked and its response traffic is automatically allowed back out, no matching outbound rule required.', 'beginner'),
('cloud', 'aws-vpc', 'overview', 'On a Network ACL, why do you typically need an inbound rule AND a separate outbound rule for ephemeral ports (1024-65535), even for a single request/response exchange?', '["NACLs block all traffic on ports above 1024 by default for security", "NACLs are stateless -- each direction of traffic is evaluated independently with no memory of prior connections, so the response traffic (which arrives on a high ephemeral port) needs its own explicit rule to be allowed through", "Ephemeral ports are reserved by AWS and cannot be used without a special rule", "This is only required for NACLs attached to database subnets, not application subnets"]', 1, 'Because a NACL has no concept of "this is a reply to traffic I already approved," both the outbound request and the inbound (or in this case outbound) response need their own explicit allow rules -- this is the most common source of NACL-related connectivity bugs.', 'intermediate'),
('cloud', 'aws-vpc', 'overview', 'Why can''t Internet Gateways be used to give a purely private subnet controlled internet access -- what''s the actual difference between an Internet Gateway and a NAT Gateway in terms of who can initiate the connection?', '["There is no difference -- IGW and NAT Gateway are interchangeable names for the same resource", "An Internet Gateway allows connections to be initiated from EITHER direction (inbound from the internet or outbound to it); a NAT Gateway only allows connections initiated FROM inside the VPC, never inbound from the internet", "An Internet Gateway can only be used with IPv6, while NAT Gateway is IPv4-only", "NAT Gateway requires a Bastion host to function, while Internet Gateway does not"]', 1, 'This directionality is the whole reason the two exist as separate concepts: an IGW makes a subnet reachable FROM the internet (public), while a NAT Gateway only lets resources reach OUT to the internet without ever being reachable from it (private, outbound-only).', 'intermediate'),

-- ---------- cloud/aws-vpc/fundamentals ----------
('cloud', 'aws-vpc', 'fundamentals', 'A VPC is created with CIDR block 10.0.0.0/16. How many total IP addresses does that CIDR range contain?', '["256", "4,096", "65,536", "16,777,216"]', 2, 'A /16 leaves 16 bits for host addresses (32 - 16 = 16), giving 2^16 = 65,536 total addresses in the range -- this is why /16 is a common choice for a whole VPC, with /24 subnets (256 addresses each) carved out of it.', 'beginner'),
('cloud', 'aws-vpc', 'fundamentals', 'Out of the 256 addresses in a /24 AWS subnet (e.g. 10.0.1.0/24), how many are actually usable for your EC2 instances or other resources?', '["256 -- all addresses in the block are usable", "254, the same as a standard on-premises /24 network", "251 -- AWS reserves 5 addresses in every subnet (network address, VPC router, DNS, a future-use reservation, and the broadcast address), leaving 256 - 5 = 251 usable", "128, because AWS always splits every subnet in half for redundancy"]', 2, 'This is a frequently-missed detail: unlike a typical on-prem /24 (which reserves only network + broadcast = 2 addresses), AWS additionally reserves the VPC router address, the DNS server address, and one address for future use -- 5 reserved addresses total, not 2.', 'intermediate'),
('cloud', 'aws-vpc', 'fundamentals', 'What is the practical difference between a route table entry that points to a NAT Gateway versus one that points to an Internet Gateway, for a private application subnet?', '["They behave identically -- both grant full bidirectional internet access", "Pointing to a NAT Gateway lets the subnet''s resources initiate outbound connections (e.g. pulling OS updates) while remaining unreachable from the internet; pointing to an IGW instead would make the subnet directly internet-reachable, defeating the purpose of keeping it private", "NAT Gateway routes only work for HTTP/HTTPS traffic, IGW routes work for all protocols", "A subnet can have both routes active simultaneously with no difference in behavior"]', 1, 'This route table choice is literally what makes a subnet private-with-outbound-access versus fully public -- swapping the NAT Gateway target for an IGW target would expose every resource in that subnet directly to the internet.', 'intermediate'),
('cloud', 'aws-vpc', 'fundamentals', 'What is the key difference between a Gateway-type VPC endpoint and an Interface-type VPC endpoint?', '["Gateway endpoints work for all AWS services; Interface endpoints only work for S3 and DynamoDB", "Gateway endpoints are only available for S3 and DynamoDB and work via a route table entry (no cost); Interface endpoints use PrivateLink (an ENI with a private IP in your subnet) and support 100+ other AWS services, at an hourly + data cost", "Interface endpoints are always free while Gateway endpoints always incur an hourly charge", "There is no functional difference -- the two names are just different console labels for the same underlying feature"]', 1, 'S3 and DynamoDB predate PrivateLink and use the older, free Gateway endpoint mechanism (a route table entry); virtually every other AWS service that supports VPC endpoints uses the newer Interface (PrivateLink) mechanism, which creates an actual ENI and has an associated cost.', 'intermediate'),
('cloud', 'aws-vpc', 'fundamentals', 'VPC A peers with VPC B, and separately VPC B peers with VPC C. Can an instance in VPC A reach an instance in VPC C through this setup?', '["Yes, VPC peering automatically routes traffic transitively through any chain of peered VPCs", "No -- VPC Peering is explicitly non-transitive; A can reach B and B can reach C, but A cannot reach C unless a direct A-C peering connection is also created (or a Transit Gateway is used instead)", "Yes, but only if all three VPCs are in the same AWS account", "No, because VPC Peering only supports connecting exactly two VPCs total across an entire AWS Organization"]', 1, 'Non-transitivity is one of VPC Peering''s defining limitations -- each peering connection is a strict point-to-point link, which is exactly the problem Transit Gateway (which DOES support transitive routing) was built to solve at scale.', 'intermediate'),

-- ---------- cloud/aws-vpc/intermediate ----------
('cloud', 'aws-vpc', 'intermediate', 'What information do VPC Flow Logs actually capture -- do they include the payload/content of network packets?', '["Yes, Flow Logs capture full packet payloads for deep packet inspection", "No -- Flow Logs capture only traffic METADATA (source/destination IP and port, protocol, byte/packet counts, accept/reject action, timestamps), never the actual packet contents", "Flow Logs capture payloads only for REJECTed traffic, to aid security investigation", "Flow Logs capture payloads only when sent to CloudWatch, not when sent to S3"]', 1, 'This is an important distinction for both cost and security-tooling design: Flow Logs tell you WHO talked to WHOM, on what port, and whether it was allowed or rejected -- useful for finding top talkers or rejected-traffic patterns -- but they never expose what was actually inside the packets.', 'intermediate'),
('cloud', 'aws-vpc', 'intermediate', 'What problem does AWS PrivateLink (via an Interface VPC Endpoint / VPC Endpoint Service) solve that VPC Peering does not?', '["PrivateLink is simply a cheaper version of VPC Peering with identical functionality", "PrivateLink exposes only a single specific service (e.g. one NLB-fronted application) to a consumer VPC, without exposing the entire provider VPC''s network the way a full VPC Peering connection would", "PrivateLink is required whenever two VPCs are in different AWS regions; Peering only works within a single region", "PrivateLink eliminates the need for security groups on the consumer side"]', 1, 'This is PrivateLink''s core value proposition: a SaaS or internal platform team can expose just one service to consumers via an Endpoint Service, without giving those consumers any network-level reach into the rest of the provider''s VPC -- something a full VPC Peering connection cannot do since it connects the whole address spaces.', 'advanced'),
('cloud', 'aws-vpc', 'intermediate', 'In a Transit Gateway hub-and-spoke design, what is the purpose of using SEPARATE Transit Gateway route tables (e.g. one for "prod" VPCs, one for "non-prod" VPCs) rather than one shared route table for every attachment?', '["Separate route tables are required by AWS -- a single shared route table is not technically possible with Transit Gateway", "Using separate route tables lets you control which VPCs can route to which other VPCs -- e.g. keeping prod and non-prod VPCs from reaching each other -- even though they all attach to the same physical Transit Gateway", "Separate route tables are purely a cost-optimization with no effect on routing/reachability", "Route tables in Transit Gateway only affect DNS resolution, not actual packet routing"]', 1, 'This is the key mechanism for network segmentation on a shared Transit Gateway hub: by associating different VPC attachments with different TGW route tables and controlling which routes get propagated into each, you can enforce that prod VPCs can reach each other and shared services, while being isolated from non-prod VPCs on the same hub.', 'advanced'),
('cloud', 'aws-vpc', 'intermediate', 'Why would a query like `SELECT srcaddr, dstport, COUNT(*) FROM vpc_flow_logs WHERE action = ''REJECT'' GROUP BY srcaddr, dstport HAVING COUNT(*) > 100` against Flow Logs data be useful for security monitoring?', '["It identifies the highest-bandwidth (most bytes transferred) connections in the VPC", "It surfaces sources making a large number of repeatedly REJECTed connection attempts to specific ports -- a common signature of port scanning or brute-force attack attempts", "It shows which EC2 instances have the lowest CPU utilization", "REJECT entries in Flow Logs only ever indicate misconfigured Security Groups, never actual attack traffic"]', 1, 'A high volume of REJECTed attempts from one source IP against specific ports is a classic scanning/probing signature -- Flow Logs analysis like this (via Athena or similar) is a standard way to surface that kind of activity from raw network metadata without needing a dedicated IDS.', 'advanced'),
('cloud', 'aws-vpc', 'intermediate', 'Why does an AWS Network Firewall sit between the Internet Gateway and the public subnets in a VPC architecture, rather than being attached directly to an individual EC2 instance like a Security Group?', '["Network Firewall is a VPC-boundary, traffic-inspection layer (supporting stateful, Suricata-compatible rules) meant to inspect and filter traffic for the whole VPC centrally, unlike Security Groups which are scoped per-instance", "Network Firewall is simply a renamed alias for Security Groups with no functional difference", "Network Firewall can only be deployed inside private subnets, never near the IGW", "EC2 instances are technically incapable of having Security Groups attached if a Network Firewall exists in the VPC"]', 0, 'Network Firewall operates as a centralized, VPC-wide inspection point capable of deep packet/content inspection (e.g. blocking traffic to known-bad domains) -- a different layer of defense from the per-instance allow-list model of Security Groups, and typically used as an additional layer rather than a replacement.', 'advanced'),

-- ---------- cloud/aws-vpc/advanced ----------
('cloud', 'aws-vpc', 'advanced', 'When you enable IPv6 on a VPC with `assign_generated_ipv6_cidr_block = true`, what size CIDR block does AWS assign to the VPC, and what size does each subnet get carved out of it?', '["A /24 to the VPC, /28 to each subnet", "A /56 to the VPC, with each subnet getting a /64 carved out of it", "A /16 to the VPC, matching the IPv4 CIDR exactly", "AWS lets you choose any IPv6 prefix length freely, with no fixed VPC/subnet split"]', 1, 'AWS-provided IPv6 allocation is fixed at this split: the VPC gets a /56 (giving room for up to 256 subnets), and each individual subnet is assigned a /64 out of that block -- unlike IPv4 CIDR sizing, this isn''t something you choose freely.', 'advanced'),
('cloud', 'aws-vpc', 'advanced', 'What problem does an Egress-Only Internet Gateway solve for a private subnet with IPv6 enabled, and how is it different from a NAT Gateway?', '["It is simply the IPv6 name for a NAT Gateway -- functionally identical, just renamed", "It allows IPv6 resources in a private subnet to initiate outbound traffic while remaining unreachable from inbound IPv6 connections -- the IPv6 equivalent of what a NAT Gateway does for IPv4, but implemented differently since IPv6 has no concept of address translation", "It only works for inbound traffic, blocking all outbound IPv6 connections", "It replaces the Internet Gateway entirely once IPv6 is enabled on a VPC"]', 1, 'IPv6 addresses are globally routable and NAT was never intended to apply to them, so AWS needed a different mechanism for the same outbound-only goal -- an Egress-Only IGW permits outbound-initiated IPv6 traffic without any inbound reachability, without doing any address translation the way a NAT Gateway does for IPv4.', 'advanced'),
('cloud', 'aws-vpc', 'advanced', 'In `cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)` (carving a subnet''s IPv6 block out of the VPC''s /56), why is the second argument `8` rather than some other number?', '["8 is an arbitrary placeholder with no real effect on the resulting subnet size", "The VPC''s IPv6 block is a /56 and each subnet needs to be a /64 -- adding 8 more bits of prefix length (56 + 8 = 64) is exactly what carves out a /64-sized subnet", "8 refers to the 8th Availability Zone in the region", "The number must always match the IPv4 subnet''s third octet"]', 1, 'This is standard Terraform `cidrsubnet` mechanics: the second argument is how many additional prefix bits to add to the base CIDR -- since AWS fixes VPC IPv6 blocks at /56 and subnets at /64, you always add exactly 8 bits (56+8=64) when subnetting IPv6, unlike IPv4 where the increment varies by how you''re sizing subnets.', 'advanced'),
('cloud', 'aws-vpc', 'advanced', 'Looking at the VPC cheatsheet''s creation sequence (`create-vpc` -> `create-subnet` -> `create-internet-gateway` -> `attach-internet-gateway` -> `create-nat-gateway`), why must `create-internet-gateway` happen as a genuinely separate step from `attach-internet-gateway`, rather than the IGW being created already-attached to a VPC?', '["This is purely a historical CLI quirk with no underlying reason -- both steps could be combined with no consequence", "An Internet Gateway is created as a standalone resource not yet associated with any VPC; attaching it is a distinct action, which is also why detaching/re-attaching an existing IGW to a different VPC is possible without recreating it", "create-internet-gateway actually creates and attaches in one step; attach-internet-gateway in the cheatsheet is a leftover redundant command", "AWS requires a manual console confirmation between the two steps for security reasons"]', 1, 'The two-step design (create the IGW as an independent object, then attach it) mirrors how most AWS networking resources work -- it''s also exactly why you can detach an IGW from one VPC and attach it to another without deleting and recreating it, which a single combined create-and-attach step wouldn''t allow.', 'advanced'),
('cloud', 'aws-vpc', 'advanced', 'The cheatsheet''s NAT Gateway creation command is `aws ec2 create-nat-gateway --subnet-id subnet-x --allocation-id eipalloc-x`. Why does a NAT Gateway require an Elastic IP allocation, when EC2 instances can get a NAT Gateway working with just a plain dynamic public IP?', '["It doesn''t actually require one -- allocation-id is an optional, ignorable parameter", "A NAT Gateway needs a stable, fixed public IP for all private-subnet resources routing through it, since instances/firewalls downstream of it (or on the other end of the connection) often allowlist by IP -- an Elastic IP guarantees that address never changes, unlike a standard dynamic public IP", "The allocation-id is only used for billing purposes and has no networking function", "NAT Gateways are billed per Elastic IP rotation, so this parameter controls cost"]', 1, 'A NAT Gateway is a shared chokepoint for potentially many private-subnet resources'' outbound traffic -- if its public IP could change unpredictably (as a standard dynamic IP can on replacement), any external allowlisting based on that IP would silently break, which is exactly the failure mode a required Elastic IP prevents.', 'advanced')
,

-- ====== AWS S3 ======

-- ---------- cloud/aws-s3/overview ----------
('cloud', 'aws-s3', 'overview', 'Why is S3 described as "not a filesystem" even though object keys like logs/2024/01/app.log look like file paths?', '["S3 actually is a filesystem, just a slow one", "Keys are flat strings identified by the whole string -- the / characters are just part of the name, there is no real directory tree being traversed to find an object", "S3 only supports keys without any slashes", "Filesystems and object storage are technically identical concepts"]', 1, 'Consoles and CLIs render common key prefixes as folders for convenience, but S3 itself just does a key lookup -- deleting the only object under a prefix makes that "folder" disappear immediately, since it was never a real directory.', 'beginner'),
('cloud', 'aws-s3', 'overview', 'What does S3''s "11 nines" (99.999999999%) figure actually describe?', '["Availability -- how often you can successfully reach the service", "Durability -- the statistical likelihood that a stored object is NOT lost over a year, which is a different (and stronger) guarantee than availability", "The percentage of requests that complete in under 1 second", "The uptime guarantee for the S3 console"]', 1, 'Durability and availability are frequently conflated but are different guarantees -- durability is about not losing your data at all; availability is about being able to reach/read it at any given moment, and varies by storage class.', 'intermediate'),
('cloud', 'aws-s3', 'overview', 'A bucket policy needs to allow s3:GetObject on every object in a bucket. Which Resource ARN format is correct?', '["arn:aws:s3:::my-bucket (the bucket ARN with no suffix)", "arn:aws:s3:::my-bucket/* (bucket ARN plus /* for object-level actions)", "arn:aws:s3:::my-bucket/ (bucket ARN with a trailing slash)", "arn:aws:s3:my-bucket:*:object/*"]', 1, 'Bucket-level actions (like s3:ListBucket) target the bucket ARN itself (arn:aws:s3:::my-bucket); object-level actions (like s3:GetObject) need the /* suffix to address the objects inside it -- mixing these up is a very common bucket-policy bug.', 'intermediate'),
('cloud', 'aws-s3', 'overview', 'S3 Block Public Access has four separate settings (BlockPublicAcls, IgnorePublicAcls, BlockPublicPolicy, RestrictPublicBuckets). Why does this matter operationally?', '["They are redundant -- enabling any one of them enables all four automatically", "They control different mechanisms (ACLs vs bucket policies, and existing vs new grants) independently -- a bucket can end up with some enabled and others not, leaving a partial gap", "Only RestrictPublicBuckets has any real effect, the other three are deprecated", "They apply only to objects uploaded before the setting was changed"]', 1, 'Treating "Block Public Access" as one on/off toggle is a common mistake -- each of the four flags governs a distinct exposure path (ACL grants vs policy grants, and whether existing public grants are also restricted), so an incomplete configuration can still leave a bucket exposed.', 'advanced'),
('cloud', 'aws-s3', 'overview', 'In the CloudFront-only bucket policy pattern (Principal: cloudfront.amazonaws.com with a Condition on AWS:SourceArn), what is this Condition actually protecting against?', '["It has no real security function, it is purely cosmetic", "Without it, ANY CloudFront distribution in ANY AWS account could be granted access by that Principal alone -- the Condition scopes the grant to one specific distribution", "It prevents the bucket from ever being made public by mistake", "It encrypts objects served through CloudFront"]', 1, 'The Service principal alone (cloudfront.amazonaws.com) identifies the AWS service, not a specific distribution -- the AWS:SourceArn condition is what actually restricts the grant to your own distribution rather than any CloudFront distribution belonging to any customer.', 'advanced'),

-- ---------- cloud/aws-s3/fundamentals ----------
('cloud', 'aws-s3', 'fundamentals', 'Why does the recommended setup order create the bucket, then immediately run put-public-access-block, before uploading any objects?', '["put-public-access-block only works on empty buckets", "Minimizing the window during which a freshly created bucket could be exposed by a default or inherited public grant before the explicit block is in place", "AWS requires this exact command order or bucket creation fails", "Objects uploaded before the block cannot be encrypted afterward"]', 1, 'This is a defense-in-depth habit: lock down public access before the bucket is used for anything, rather than treating it as a later cleanup step that might get skipped.', 'beginner'),
('cloud', 'aws-s3', 'fundamentals', 'What does enabling S3 bucket versioning actually change when an existing object key is overwritten with new content?', '["The old content is deleted immediately to save space", "The old version is kept and given a version ID; the new upload becomes the current version, and both remain retrievable by version ID", "Overwrites are blocked entirely once versioning is on", "Versioning only applies to objects uploaded after enabling it, and has no effect on subsequent overwrites"]', 1, 'This is exactly the recovery mechanism versioning provides -- an overwrite (or even a delete, which just adds a delete marker) does not destroy the previous version, so it can be restored by referencing its version ID.', 'intermediate'),
('cloud', 'aws-s3', 'fundamentals', 'In the DenyUnencryptedPuts bucket policy example (Effect: Deny, Action: s3:PutObject, Condition: StringNotEquals on s3:x-amz-server-side-encryption), what is the practical effect?', '["It encrypts every object automatically without the uploader doing anything", "It rejects any PutObject request that does NOT explicitly request server-side encryption with the specified algorithm, forcing uploaders to opt in", "It only applies to objects larger than 5GB", "It has no effect because Deny statements are ignored when an Allow statement also exists"]', 1, 'A Deny statement with a negated condition is a common pattern for enforcing a requirement (here, that every PUT specifies SSE) rather than just permitting an action -- explicit Deny always wins over any Allow in IAM policy evaluation.', 'advanced'),
('cloud', 'aws-s3', 'fundamentals', 'When generating a presigned URL for object download with boto3''s generate_presigned_url, what credentials does the person who receives and uses that URL need?', '["Their own full AWS IAM credentials", "None -- the URL itself is cryptographically signed using the credentials of whoever generated it, and is valid for the specified time window without the requester needing any AWS credentials at all", "A temporary IAM user account created specifically for them", "Only a valid AWS account ID, no keys required"]', 1, 'This is the core value of presigned URLs: they let you grant scoped, time-limited access to a private object to someone (or something) with zero AWS credentials of their own -- the signature itself carries the authorization.', 'intermediate'),
('cloud', 'aws-s3', 'fundamentals', 'A lifecycle rule transitions objects under logs/ to STANDARD_IA at 30 days and to GLACIER at 90 days. Why is 30 days the minimum before the first transition, specifically to Standard-IA?', '["AWS enforces a 30-day minimum storage duration for Standard-IA and One Zone-IA, reflecting that those classes are billed with an implicit minimum retention -- transitioning sooner isn''t just discouraged, the minimum exists at the pricing model level", "It is an arbitrary example value with no underlying constraint", "30 days is required so CloudTrail has time to log the object''s access history first", "Lifecycle rules cannot execute faster than once every 30 days regardless of the Days value used"]', 0, 'Standard-IA and One Zone-IA have a minimum storage duration charge (billed as if kept at least that long even if deleted/transitioned earlier), which is why lifecycle guidance treats 30 days as a practical floor for transitioning into those classes.', 'advanced'),

-- ---------- cloud/aws-s3/intermediate ----------
('cloud', 'aws-s3', 'intermediate', 'In the S3-to-Lambda-to-DynamoDB pipeline example, why does the handler call s3.get_object and stream/read the body rather than assuming the whole file is small?', '["Lambda cannot process files larger than 1KB", "Lambda functions have limited memory and execution time -- code written to stream/process incrementally scales to larger files without risking an out-of-memory failure that a naive load-everything-at-once approach would hit", "DynamoDB rejects writes from functions that read files into memory first", "S3 objects are automatically split into chunks that must be read separately"]', 1, 'This is a common production pattern: even though the example reads the whole body in this simplified handler, treating large-file handling carefully (streaming, chunking, or at minimum being aware of Lambda''s memory ceiling) matters once files are big enough that "just load it all" stops being safe.', 'intermediate'),
('cloud', 'aws-s3', 'intermediate', 'What is a hard prerequisite for setting up S3 Cross-Region Replication between a source and destination bucket?', '["The buckets must be in the same AWS account", "Versioning must be enabled on BOTH the source bucket and the destination bucket -- replication will not work with only one side versioned", "The destination bucket must use S3 Standard storage class only", "Both buckets must have identical bucket policies"]', 1, 'This is a frequently missed step -- enabling versioning only on the source bucket (which is what an incomplete example might show) is not sufficient; CRR/SRR requires versioning on both source and destination before the replication configuration will actually work.', 'intermediate'),
('cloud', 'aws-s3', 'intermediate', 'What problem does S3 Object Lambda solve that a plain S3 GetObject cannot?', '["It makes GetObject requests faster by caching results", "It lets you insert a Lambda function between S3 and the requester to transform/filter the object''s content on the fly (e.g. redacting PII for non-owners) without maintaining a second, transformed copy of the data", "It automatically compresses every object before returning it", "It replaces the need for bucket policies entirely"]', 1, 'Without Object Lambda, per-requester transformations (like redacting sensitive fields based on who is asking) would require either duplicating data into multiple pre-transformed copies or building a separate proxy service -- Object Lambda does the transformation inline at read time instead.', 'advanced'),
('cloud', 'aws-s3', 'intermediate', 'In the replication configuration example, what does ReplicationTime with Status: Enabled and Time: 15 minutes configure?', '["The maximum time S3 will wait before deleting the source object after replication", "S3 Replication Time Control (RTC) -- a service-level agreement that 99.9% of new objects are replicated within the specified time window (here, 15 minutes), with accompanying replication metrics", "A retry limit -- replication attempts are abandoned after 15 minutes", "The interval at which the destination bucket polls the source bucket for changes"]', 1, 'By default, standard S3 replication has no time guarantee (usually happens within minutes but isn''t SLA-backed) -- enabling RTC adds a predictable, monitorable time bound, which matters for compliance/DR scenarios with a defined recovery point objective.', 'advanced'),
('cloud', 'aws-s3', 'intermediate', 'After the pipeline example processes a CSV successfully, it calls s3.copy_object to move the file to a processed/ prefix and then s3.delete_object on the original. Why two separate calls instead of one "move" operation?', '["S3 has no native rename/move operation -- an object''s key is part of its identity, so relocating it means copying to the new key and deleting the old one", "delete_object is optional and included only for cleanup, copy_object alone would fully move the file", "This is a bug in the example; a single s3.move_object call should have been used instead", "AWS Lambda requires two separate API calls for any S3 write operation"]', 0, 'This is the same underlying reason aws s3 mv is implemented as copy-then-delete under the hood -- since a key is essentially the object''s address, there is no atomic rename primitive in the S3 API itself.', 'intermediate'),

-- ---------- cloud/aws-s3/advanced ----------
('cloud', 'aws-s3', 'advanced', 'What is the main advantage of S3 Select over downloading a full CSV/JSON/Parquet object and filtering it client-side?', '["S3 Select is free while normal GetObject requests are not", "S3 Select runs the SQL-like filter/aggregation server-side and streams back only the matching results, avoiding the cost and time of transferring the entire object just to discard most of it", "S3 Select converts any file format to Parquet automatically", "S3 Select removes the need for IAM permissions on the bucket"]', 1, 'For a large data lake file where only a small subset of rows/columns is actually needed, S3 Select can dramatically cut both data transfer and client-side processing compared to pulling the whole object down first.', 'intermediate'),
('cloud', 'aws-s3', 'advanced', 'In the S3 Batch Operations re-encryption example, what role does the manifest (built from an S3 Inventory report) play?', '["It is purely a log of what the batch job did after the fact", "It is the input list telling the batch job exactly which objects to operate on -- without it, there is no defined set of targets for the millions-of-objects-scale operation", "It replaces the need for an IAM role in the batch job", "It is required only when re-encrypting objects smaller than 1MB"]', 1, 'S3 Batch Operations needs an explicit list of target objects to act on at scale; an S3 Inventory report is a common, efficient way to generate that manifest for buckets with too many objects to enumerate via a live LIST call.', 'advanced'),
('cloud', 'aws-s3', 'advanced', 'Why does the account-level put-public-access-block command (via s3control) matter in addition to the per-bucket version shown elsewhere in this course?', '["It does the same thing and is redundant with the bucket-level setting", "It sets a default that applies across every bucket in the account, including future buckets -- a safety net against a new or misconfigured bucket being created without the per-bucket protection", "It only affects buckets created in us-east-1", "It disables S3 entirely for the account, functioning as a kill switch"]', 1, 'The recommended production practice (also reflected in the incident-response guidance for an accidentally public bucket) is to set this at the account level as a baseline, not rely solely on remembering to configure it correctly on every individual bucket.', 'advanced'),
('cloud', 'aws-s3', 'advanced', 'What kind of problem is Macie designed to find that a bucket policy or encryption setting cannot address?', '["Whether a bucket''s objects are publicly accessible", "Sensitive data (like PII) that has already been stored in S3 objects, regardless of how well the bucket itself is locked down -- it inspects content, not access configuration", "Whether versioning is enabled on a bucket", "Whether a bucket is using the correct storage class for its access pattern"]', 1, 'A perfectly locked-down bucket (no public access, encrypted, IAM-restricted) can still contain sensitive data that shouldn''t be there in the first place, or shouldn''t be accessible to as many principals as it is -- Macie''s job is discovering that at the content level, which access-control tooling alone cannot do.', 'advanced'),
('cloud', 'aws-s3', 'advanced', 'In the S3 Batch Operations job definition, the manifest Spec Format is "S3InventoryReport_CSV_20161130" and includes both an ObjectArn and an ETag for the manifest location. Why does the ETag matter here?', '["It verifies the checksum of every object the batch job will touch, not just the manifest", "It pins the batch job to the exact version/content of the manifest file at the time the job was created, preventing the job from silently using a different manifest if the file at that key gets overwritten before the job runs", "ETag is required by IAM to authorize the s3control:CreateJob call", "It has no functional purpose and is optional metadata"]', 1, 'Specifying the ETag alongside the manifest location is what makes the batch job''s input deterministic -- without it, an inventory report object could be overwritten between job creation and execution with no way to detect the mismatch.', 'advanced')
,

-- ====== AWS RDS ======

-- ---------- cloud/aws-rds/overview ----------
('cloud', 'aws-rds', 'overview', 'In RDS Multi-AZ, can an application read from the standby instance to offload traffic from the primary?', '["Yes, the standby accepts read queries just like a read replica", "No -- the standby exists purely for automatic failover and is not reachable for queries; only a Read Replica (a separate feature) can serve reads", "Yes, but only for SELECT queries under 1MB", "Only if Performance Insights is enabled on the standby"]', 1, 'Multi-AZ and Read Replicas are frequently confused: Multi-AZ''s standby is synchronously replicated purely for HA and cannot be queried, while a Read Replica is asynchronously replicated specifically so it CAN be queried.', 'beginner'),
('cloud', 'aws-rds', 'overview', 'Why does the Terraform example in this course fetch database credentials from AWS Secrets Manager (or set manage_master_user_password = true) instead of hardcoding a password in the .tf file?', '["Terraform cannot store string values longer than 20 characters", "Hardcoded passwords end up committed to version control in plaintext and are never rotated automatically; Secrets Manager keeps the credential out of source code and can rotate it on a schedule", "Secrets Manager is required for RDS to boot at all", "It has no real benefit, it is only a style preference"]', 1, 'A password committed to a Terraform file lives in git history forever and has to be rotated manually everywhere it is used -- Secrets Manager (or manage_master_user_password) removes the credential from source entirely and can rotate it automatically.', 'beginner'),
('cloud', 'aws-rds', 'overview', 'What does setting publicly_accessible = false on an aws_db_instance actually protect against, given that a security group already restricts inbound traffic?', '["Nothing -- it is redundant with the security group and can be omitted", "It prevents RDS from assigning a public IP/DNS endpoint at all, which is a second layer of defense beyond the security group -- if the security group is later misconfigured to allow 0.0.0.0/0, a private-only instance still isn''t reachable from the internet", "It disables encryption at rest", "It forces the instance into a single-AZ deployment"]', 1, 'Defense in depth: publicly_accessible=false means there is no route from the internet to the instance at all, so a future security-group mistake alone can''t expose the database -- both controls matter independently.', 'intermediate'),
('cloud', 'aws-rds', 'overview', 'In the Aurora Serverless v2 example, why can min_capacity be set to 0.5 ACUs while max_capacity is set to 64 ACUs?', '["ACUs must always be a whole number, so 0.5 is invalid", "Aurora Serverless v2 scales capacity within that range automatically based on load, in fine-grained increments, rather than requiring you to provision for peak load permanently", "0.5 and 64 refer to storage in TB, not compute", "Setting a range disables Multi-AZ for the cluster"]', 1, 'Serverless v2 continuously adjusts compute capacity between the configured min and max ACUs based on actual load, so you pay closer to what you use instead of sizing permanently for the worst case.', 'intermediate'),
('cloud', 'aws-rds', 'overview', 'Why must storage_encrypted be decided at RDS instance creation time rather than turned on later for an existing unencrypted production database?', '["AWS bills differently for encrypted vs unencrypted storage and won''t allow switching", "Encryption is applied at the underlying storage layer at creation time; enabling it after the fact requires snapshotting the unencrypted instance, copying that snapshot with encryption enabled, and restoring a new instance from the encrypted copy", "storage_encrypted can be toggled with a simple modify-db-instance call and a reboot", "Only Aurora clusters support encryption, not standard RDS instances"]', 1, 'This is a common surprise for teams retrofitting security requirements onto an existing database -- there is no in-place toggle; the snapshot-copy-encrypted-restore workflow is required and involves a new instance identifier/endpoint.', 'intermediate'),

-- ---------- cloud/aws-rds/fundamentals ----------
('cloud', 'aws-rds', 'fundamentals', 'In the fundamentals Terraform example, why does the aws_security_group for RDS only allow inbound traffic from var.app_sg_id rather than from a CIDR range like 10.0.0.0/16?', '["CIDR ranges are not supported in RDS security group rules", "Referencing another security group means only resources that are actually members of the app tier''s security group can connect, regardless of which subnet or IP they end up with -- tighter and more maintainable than trusting an entire IP range", "It has no functional difference from a CIDR rule", "app_sg_id is required syntax and has no security meaning"]', 1, 'Security-group-to-security-group references scope access to a specific tier of resources by identity rather than by network location, which stays correct even if subnet CIDR ranges change later.', 'intermediate'),
('cloud', 'aws-rds', 'fundamentals', 'What is the actual difference between a Parameter Group and an Option Group in RDS?', '["They are two names for the same feature", "A Parameter Group configures engine runtime settings (e.g. max_connections, log_min_duration_statement) and some changes require a reboot while others apply dynamically; an Option Group adds optional engine features (e.g. Oracle TDE, SQL Server native backup) that aren''t plain configuration values", "Option Groups are only used for MySQL, Parameter Groups only for PostgreSQL", "Parameter Groups can only be edited through the AWS Console, never Terraform"]', 1, 'Parameter Groups tune how the engine behaves; Option Groups bolt on discrete engine features. Confusing the two is a common mistake since both are attached to the instance similarly.', 'beginner'),
('cloud', 'aws-rds', 'fundamentals', 'What problem does RDS Proxy solve for a Lambda function that queries a database on every invocation?', '["It makes SQL queries execute faster by rewriting them", "Without pooling, many concurrent Lambda invocations can each open a new direct database connection and exhaust the database''s max_connections limit; RDS Proxy pools and reuses connections so bursts of Lambda invocations don''t overwhelm the database", "It replaces the need for a VPC configuration on the Lambda function", "It automatically creates read replicas on demand"]', 1, 'Lambda''s scale-out model means concurrency can spike quickly -- each concurrent execution wanting its own DB connection is exactly the failure mode (\'too many connections\') that a pooling proxy in front of the database is designed to absorb.', 'intermediate'),
('cloud', 'aws-rds', 'fundamentals', 'Why is Aurora described as having a different storage architecture from standard RDS, rather than just being "RDS running MySQL with extra features"?', '["Aurora and RDS use identical EBS-backed storage; the difference is purely in the console UI", "Aurora uses a custom distributed storage layer that keeps 6 copies of data across 3 AZs automatically, versus standard RDS engines which run on ordinary EBS volumes attached to a single instance (mirrored to a standby only if Multi-AZ is enabled) -- a materially different underlying architecture, not just a config difference", "Aurora only differs from RDS in its billing model", "RDS and Aurora both auto-scale storage to 128TB identically"]', 1, 'Even though Aurora is launched through the same RDS console/API, its storage engine is a distinct, purpose-built distributed system -- this is why Aurora achieves faster failover and higher throughput rather than just being a pricing tier of standard RDS.', 'intermediate'),
('cloud', 'aws-rds', 'fundamentals', 'Per this course''s corrected note, does Aurora''s Backtrack feature (rewinding a database to a prior second) work identically on both Aurora MySQL and Aurora PostgreSQL?', '["Yes, Backtrack is available and identical on both engines", "No -- Backtrack is an Aurora MySQL-only feature; Aurora PostgreSQL does not support it", "Backtrack only exists for standard RDS PostgreSQL, not Aurora at all", "Backtrack requires Aurora Serverless v1, which is deprecated"]', 1, 'This is a specific, easy-to-assume-is-universal Aurora feature that is actually scoped to one engine family -- worth double-checking before designing a recovery strategy around it.', 'intermediate'),

-- ---------- cloud/aws-rds/intermediate ----------
('cloud', 'aws-rds', 'intermediate', 'When you create a cross-region read replica for disaster recovery, what replication behavior should you expect compared to a same-region read replica?', '["Cross-region replicas use synchronous replication for extra safety", "Both same-region and cross-region read replicas use asynchronous replication -- the cross-region replica can lag behind the primary, and network distance between regions can add to that lag", "Cross-region replicas cannot serve read traffic, only same-region ones can", "Cross-region replicas automatically become the new primary if the source region fails"]', 1, 'Read replicas -- whether same-region or cross-region -- are always asynchronous; a cross-region replica adds a DR and geo-latency option but does not change the fundamental replication model or provide automatic failover on its own.', 'intermediate'),
('cloud', 'aws-rds', 'intermediate', 'In the RDS Proxy + Lambda example using IAM authentication, why is generate_db_auth_token() wrapped with an in-memory cache (lru_cache) instead of being called on every single invocation?', '["IAM auth tokens are billed per generation, so caching saves money", "The generated auth token acts as the password and is valid for a limited window (about 15 minutes); generating a fresh token on every invocation is unnecessary overhead when a cached one is still valid", "Without caching, generate_db_auth_token() would return a different database entirely each time", "IAM authentication does not support token reuse under any circumstances"]__PLACEHOLDER__', 1, 'IAM auth tokens for RDS are time-limited credentials, not single-use ones -- reusing a still-valid cached token avoids the latency and API-call overhead of regenerating one on every Lambda invocation.', 'advanced'),
('cloud', 'aws-rds', 'intermediate', 'What does Aurora Global Database provide that a standard cross-region Aurora read replica alone does not?', '["Global Database eliminates the need for any read replicas within the primary region", "Global Database is purpose-built for multi-region DR: it replicates to up to several secondary regions with typically sub-second lag and supports a managed failover operation to promote a secondary region to primary", "Global Database only works with Aurora MySQL, never PostgreSQL", "Global Database requires manually running pg_dump/mysqldump on a schedule"]', 1, 'Global Database is a dedicated Aurora feature for cross-region resilience with fast, low-lag replication and a managed promotion workflow -- a more purpose-built DR tool than assembling ad hoc cross-region replicas yourself.', 'advanced'),
('cloud', 'aws-rds', 'intermediate', 'Why does the example application connection pattern point writes to the primary endpoint and reads to a separate replica endpoint, rather than sending all traffic to one endpoint?', '["RDS silently load-balances all traffic across primary and replicas automatically, so the split is only cosmetic", "A read replica cannot accept write (INSERT/UPDATE/DELETE) traffic at all -- only the primary can -- so the application must route writes and reads to their respective endpoints explicitly", "The primary endpoint is deprecated in favor of replica endpoints", "This pattern is only needed for Aurora, never for standard RDS"]', 1, 'This read/write split has to be handled at the application (or proxy) layer -- RDS does not automatically route queries between primary and replicas, so sending a write to a replica endpoint will simply fail.', 'intermediate'),
('cloud', 'aws-rds', 'intermediate', 'What is the primary risk of promoting a read replica to a standalone instance during a failover test, as shown in this section?', '["Promotion is instant and fully reversible with no side effects", "Promotion breaks replication permanently for that instance -- once promoted, it becomes an independent primary and can no longer be turned back into a replica of the original source without re-establishing replication from scratch", "Promoted replicas lose all previously replicated data", "Only Aurora replicas can be promoted; standard RDS replicas cannot"]', 1, 'Promotion is a one-way operation for that replica -- this is why it should be treated deliberately (e.g. as part of a planned failover or DR drill), not as a reversible toggle.', 'advanced'),

-- ---------- cloud/aws-rds/advanced ----------
('cloud', 'aws-rds', 'advanced', 'What is the main advantage of an RDS Blue-Green Deployment for a major engine version upgrade compared to an in-place upgrade?', '["Blue-Green deployments are always cheaper than in-place upgrades", "Blue-Green creates a fully separate, real running copy (the green environment) that can be tested against before switching production traffic over, keeping downtime to the brief switchover window instead of the whole upgrade+validation process", "Blue-Green deployments skip the need for a parameter group entirely", "Blue-Green deployments only work for Aurora, never standard RDS"]', 1, 'Because the green environment is a real, independently testable database, you validate the upgrade before committing to it -- the production-facing downtime is limited to the switchover itself rather than the whole upgrade and verification process.', 'advanced'),
('cloud', 'aws-rds', 'advanced', 'After a successful Blue-Green switchover, what does the old "blue" (pre-upgrade) environment become, and why does that matter operationally?', '["It is deleted automatically the moment switchover completes", "It becomes the new \"green\" environment -- kept around rather than immediately destroyed, which gives you an easy rollback path if a problem surfaces shortly after switchover", "It keeps serving production write traffic in parallel with the new primary", "It automatically converts into a cross-region read replica"]', 1, 'Keeping the old environment around post-switchover (until it is deliberately deleted) is what makes Blue-Green meaningfully safer than a one-way in-place upgrade -- there is a real rollback target immediately after cutover.', 'advanced'),
('cloud', 'aws-rds', 'advanced', 'In the bloat-checking query against pg_stat_user_tables, what does a high dead_pct (ratio of n_dead_tup to total tuples) actually indicate?', '["The table has too many indexes", "A large share of a table''s rows are dead tuples left behind by UPDATE/DELETE operations that autovacuum has not yet reclaimed, which can bloat storage and slow down queries until vacuumed", "The table is missing a primary key", "Replication has fallen behind on that specific table"]', 1, 'PostgreSQL''s MVCC model leaves old row versions behind after UPDATE/DELETE until vacuum cleans them up -- a high dead-tuple percentage is the signal that autovacuum isn''t keeping pace, which is exactly what this monitoring query is built to catch.', 'advanced'),
('cloud', 'aws-rds', 'advanced', 'Why does the Performance Insights example group query load by db.sql.tokenized_id rather than the raw literal SQL text of each query?', '["tokenized_id is required because Performance Insights cannot store raw SQL at all", "Tokenizing normalizes queries that differ only by literal parameter values (e.g. WHERE id = 5 vs WHERE id = 9) into the same logical query, so load from many parameterized executions of the \"same\" query is aggregated together instead of being split across near-duplicate entries", "tokenized_id sorts queries alphabetically for the report", "It has no functional purpose, it is only a display label"]', 1, 'Without normalization, thousands of executions of what is really one query shape (just with different literal values) would each show up as a distinct entry, making it hard to see which query pattern is actually driving load -- tokenization solves that.', 'advanced'),
('cloud', 'aws-rds', 'advanced', 'The cheatsheet section shows aws rds reboot-db-instance --force-failover as a way to test Multi-AZ failover. What does --force-failover specifically require to be a valid test?', '["It works on any RDS instance regardless of configuration", "The instance must have Multi-AZ enabled -- --force-failover reboots by failing over to the standby, so it has no standby to fail over to (and will error) on a Single-AZ instance", "It permanently disables Multi-AZ after running once", "It only works on Aurora clusters, never standard RDS instances"]', 1, 'This flag is specifically for validating that automatic failover actually works on a Multi-AZ instance -- attempting it against a Single-AZ instance doesn''t have a standby to fail over to, so the operation isn''t meaningful (or valid) there.', 'intermediate')


ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
